/**
 * Enrich the Shared Web Hosting plan tiers (HostingPlan rows) with the fields added
 * for the production-readiness push: bundled email `mailboxes`, `freeMigration`,
 * `featured`, and a `tagline`.
 *
 * UPDATE-IN-PLACE by design: for a plan that already exists (prod's Starter /
 * Business / Pro), the upsert's `update` sets ONLY the new fields — the name,
 * price, and resource limits are left exactly as they are. The `create` block only
 * fires in a fresh environment (e.g. a clean staging DB) and carries the canonical
 * tier definition so the storefront isn't empty there.
 *
 * Idempotent. Safe to re-run.
 * Run: cd /opt/nxeon && npx tsx prisma/seed-hosting-plans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

const PHP = "8.1,8.2,8.3";

// slug → the NEW fields to set in place, plus canonical create-defaults (matching
// the live prod tiers) used only when the plan doesn't exist yet.
type Spec = {
  slug: string;
  newFields: { mailboxes: number; freeMigration: boolean; featured: boolean; tagline: string };
  create: { name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; sortOrder: number };
};

const SPECS: Spec[] = [
  {
    slug: "starter",
    newFields: { mailboxes: 1, freeMigration: false, featured: false, tagline: "Perfect for getting your first website online." },
    create: { name: "Starter", priceCents: 299, diskGB: 10, maxSites: 1, maxDatabases: 2, bandwidthTB: 1, sortOrder: 0 },
  },
  {
    slug: "business",
    newFields: { mailboxes: 3, freeMigration: true, featured: true, tagline: "For growing businesses running several sites." },
    create: { name: "Business", priceCents: 499, diskGB: 20, maxSites: 10, maxDatabases: 25, bandwidthTB: 2, sortOrder: 1 },
  },
  {
    slug: "pro",
    newFields: { mailboxes: 5, freeMigration: true, featured: false, tagline: "Maximum resources for high-traffic sites." },
    create: { name: "Pro", priceCents: 899, diskGB: 30, maxSites: 50, maxDatabases: 100, bandwidthTB: 4, sortOrder: 2 },
  },
];

async function main() {
  let updated = 0;
  let created = 0;
  for (const s of SPECS) {
    const existing = await db.hostingPlan.findUnique({ where: { slug: s.slug }, select: { name: true, priceCents: true } });
    await db.hostingPlan.upsert({
      where: { slug: s.slug },
      update: { ...s.newFields }, // in place: ONLY the new fields
      create: { slug: s.slug, ...s.create, ...s.newFields, phpVersions: PHP, active: true },
    });
    if (existing) {
      updated++;
      console.log(`  updated  ${existing.name.padEnd(10)} ($${(existing.priceCents / 100).toFixed(2)} kept) → ${s.newFields.mailboxes} mailbox(es)${s.newFields.freeMigration ? " · free migration" : ""}${s.newFields.featured ? " · ★" : ""}`);
    } else {
      created++;
      console.log(`  created  ${s.create.name.padEnd(10)} ($${(s.create.priceCents / 100).toFixed(2)}) → ${s.newFields.mailboxes} mailbox(es)${s.newFields.freeMigration ? " · free migration" : ""}${s.newFields.featured ? " · ★" : ""}`);
    }
  }
  const total = await db.hostingPlan.count();
  console.log(`\nHostingPlans: ${updated} updated in place, ${created} created. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";
import { randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";
import { assertDbTarget } from "../scripts/db-target-guard.ts";

// Confirm the target database BEFORE constructing the client, so a wrong target
// is refused without a connection ever being opened. On 2026-07-26 this script
// was run against PRODUCTION by accident from a scratch tree whose symlinked
// node_modules made Prisma load /opt/nxeon/.env; it was idempotent and did no
// damage, which is luck rather than a control. See scripts/db-target-guard.ts.
//
//   NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed.ts
assertDbTarget("prisma/seed.ts");

const db = new PrismaClient();

// Prices include a dedicated IPv4 (the $3/mo IP cost is folded into the plan
// price and `dedicated_ip_price_cents` defaults to 0), so "dedicated IP included"
// marketing is accurate and customers see one honest number.
const plans = [
  { slug: "nano",     name: "Nano",     cpuCores: 1, ramMB: 1024,  diskGB: 15,  bandwidthTB: 1, priceCents: 649,  sortOrder: 1 },
  { slug: "starter",  name: "Starter",  cpuCores: 1, ramMB: 2048,  diskGB: 25,  bandwidthTB: 1, priceCents: 899,  sortOrder: 2 },
  { slug: "standard", name: "Standard", cpuCores: 2, ramMB: 4096,  diskGB: 50,  bandwidthTB: 2, priceCents: 1299, sortOrder: 3 },
  { slug: "pro",      name: "Pro",      cpuCores: 3, ramMB: 8192,  diskGB: 80,  bandwidthTB: 4, priceCents: 2099, sortOrder: 4 },
  { slug: "max",      name: "Max",      cpuCores: 4, ramMB: 16384, diskGB: 120, bandwidthTB: 8, priceCents: 3299, sortOrder: 5 },
];

const osTemplates = [
  { slug: "ubuntu-24-04", name: "Ubuntu 24.04 LTS", vmid: 9000 },
  { slug: "debian-13",    name: "Debian 13",        vmid: 9001 },
];

async function main() {
  for (const p of plans) {
    await db.plan.upsert({ where: { slug: p.slug }, update: p, create: p });
  }
  for (const t of osTemplates) {
    await db.osTemplate.upsert({ where: { slug: t.slug }, update: t, create: t });
  }

  // Products/apps the project boards are grouped under. Idempotent (upsert by
  // slug). Board.name is matched against these to backfill existing boards.
  //
  // The working-context fields (codePath/repoUrl/context) are defaults for a
  // FRESH install only: they go in `create` but deliberately NOT in `update`, so
  // a re-seed of an existing DB never clobbers a value a human or a later Claude
  // session edited through the board's App settings. `update` stays limited to
  // name + color, exactly as before.
  const apps = [
    {
      slug: "nxeon",
      name: "Nxeon",
      color: "#7c5cf7",
      codePath: "/opt/nxeon",
      repoUrl: "https://github.com/santino1233/nxeon",
      context:
        'Nxeon platform — this admin app itself. Runs on the Proxmox host. Stack: Next.js (App Router) + Prisma + Tailwind. Code: /opt/nxeon. Prod: systemd `nxeon-web` (:80) + `nxeon-worker`. Staging: /opt/nxeon-staging, `nxeon-staging-web` (:8080). DB: Postgres "nxeon" (Prisma; uses `prisma db push`, NOT migrate). Deploy: commit (post-commit hook auto-pushes to GitHub main) → `bash scripts/deploy-staging.sh` → `bash scripts/promote-production.sh`. Admin panel is served ONLY on the obscured host 4j3d7gkr2wcbi34.nxeon.cloud. NOTE: direct prod deploys via bash get safety-classifier-blocked — delegate deploys to a general-purpose subagent.',
    },
    {
      slug: "soul-pilates",
      name: "Soul Pilates",
      color: "#f472b6",
      codePath: "/opt/soulpilates",
      repoUrl: null,
      context:
        'Soul Pilates — LIVE studio-booking business (real customers — be careful). Server: studionexis-soul @ 51.79.226.200 (SSH via platform creds: decryptSecret(server.rootPasswordEnc)). Stack: .NET API + frontend, docker-compose. Code: /opt/soulpilates (docker-compose.prod.yml, compose project "soulpilates", env /opt/soulpilates/prod.env). Containers: soulpilates-prod-backend (.NET SoulPilates.API, host :8391→8080), -frontend (:3719), -mongo (db "soulpilates"), -redis, -rustfs (:6324), -glitchtip. Staging stack: /opt/soulpilates-staging (soulpilates-staging-*, frontend :3819, backend :8491). nginx on box: /etc/nginx/conf.d/00-soulpilates-com.conf + 01-soulpilates-staging.conf. Deploy: edit prod.env or rebuild image, then `cd /opt/soulpilates && docker compose -f docker-compose.prod.yml -p soulpilates --env-file prod.env up -d --force-recreate --no-deps <service>`. Email: sends via Nxeon Mail (mail.nxeon.cloud:587 as noreply@soulpilates.com.vn); templates are compiled into SoulPilates.Services.dll (not file-extractable). Mongo backups: /usr/local/bin/soulpilates-backup.sh (cron every 6h).',
    },
    {
      slug: "studionexis",
      name: "Studio Nexis",
      color: "#38bdf8",
      codePath: "/opt/nexis",
      repoUrl: "https://github.com/santino1233/studionexis",
      context:
        'Studio Nexis — Next.js studio-management app. Server: nexis-app @ 51.79.226.215 (SSH via platform creds). Repo: github.com/santino1233/studionexis. Code: /opt/nexis (prod) + /opt/nexis-staging (staging). Stack: Next.js 16 (App Router, Node 22, `next start -p 3105`, NOT standalone — copy the built .next), Prisma. Prod: systemd nexis-next.service (:3105). Staging: nexis-staging.service (:3106). DB: Postgres in the `nexis-postgres` container (bind 127.0.0.1:5599; DBs nexis + nexis_staging). Multi-tenant middleware: hq.studionexis.com = HQ portal, app./new. = admin hosts, HQ_PATH gates /hq, *.studionexis.com wildcard = tenants. Serves studionexis.com + www/hq/app/new/stg + tenant subdomains. Deploy: build .next + `systemctl restart nexis-next`. Wildcard cert /etc/letsencrypt/live/studionexis-wildcard/ (Cloudflare DNS-01 via /root/.cf-studionexis.ini). nginx: /etc/nginx/conf.d/studionexis.conf (nginx 1.24 → `listen 443 ssl http2`, not `http2 on`).',
    },
  ];
  for (const a of apps) {
    await db.app.upsert({ where: { slug: a.slug }, update: { name: a.name, color: a.color }, create: a });
  }
  // Backfill: attach existing boards to an app by matching Board.name to an app
  // name (case-insensitive). Boards with no match stay appId=null ("Unassigned").
  const seededApps = await db.app.findMany();
  for (const board of await db.board.findMany({ where: { appId: null } })) {
    const match = seededApps.find((ap) => ap.name.toLowerCase() === board.name.trim().toLowerCase());
    if (match) await db.board.update({ where: { id: board.id }, data: { appId: match.id } });
  }

  // Marketing Agent Phase 1 — default monitoring sources. Idempotent: only seeds
  // when no sources exist yet, so an operator's edits are never overwritten.
  // The discovery sweep reads these PUBLIC feeds read-only and drafts DISCLOSED
  // replies for a human to post manually — it never posts anything itself.
  try {
    const sourceCount = await db.marketingSource.count();
    if (sourceCount === 0) {
      const gameKeywords = [
        "best minecraft host",
        "minecraft server host",
        "which host",
        "recommend a host",
        "shockbyte",
        "bisecthosting",
        "looking for a host",
        "game server hosting",
        "cheap game server",
      ];
      const vpsKeywords = [
        "looking for a host",
        "which host",
        "recommend a vps",
        "cheap vps",
        "best vps",
        "hostinger alternative",
        "digitalocean alternative",
        "vultr alternative",
        "contabo alternative",
        "vps recommendation",
      ];
      const defaults = [
        { type: "reddit", target: "admincraft", keywords: gameKeywords },
        { type: "reddit", target: "MinecraftServer", keywords: gameKeywords },
        { type: "reddit", target: "feedthebeast", keywords: gameKeywords },
        { type: "reddit", target: "playrust", keywords: ["server host", "recommend a host", "cheap host", "which host"] },
        { type: "reddit", target: "Palworld", keywords: ["dedicated server host", "server hosting", "which host", "recommend a host"] },
        { type: "reddit", target: "selfhosted", keywords: vpsKeywords },
        { type: "reddit", target: "webhosting", keywords: vpsKeywords },
        { type: "reddit", target: "VPS", keywords: vpsKeywords },
        { type: "hackernews", target: "cheap vps hosting", keywords: vpsKeywords },
      ];
      for (const d of defaults) {
        await db.marketingSource.create({ data: { type: d.type, target: d.target, keywords: d.keywords, active: true } });
      }
      console.log(`Seeded ${defaults.length} marketing sources`);
    }
  } catch (e) {
    console.error("Marketing source seed skipped:", e);
  }

  const adminEmail = "admin@nxeon.local";
  const existing = await db.user.findUnique({ where: { email: adminEmail } });
  if (!existing) {
    const password = randomBytes(12).toString("base64url");
    await db.user.create({
      data: {
        email: adminEmail,
        name: "Nxeon Admin",
        role: "ADMIN",
        passwordHash: await bcrypt.hash(password, 12),
      },
    });
    const credFile = process.env.NXEON_CRED_FILE ?? "/root/nxeon-credentials.txt";
    writeFileSync(credFile, `Nxeon admin login\nURL: ${process.env.APP_URL ?? "http://51.79.162.96/"}\nEmail: ${adminEmail}\nPassword: ${password}\n`, { mode: 0o600 });
    // Report the path actually written. This used to hardcode
    // /root/nxeon-credentials.txt, so with NXEON_CRED_FILE set it told the
    // operator to look in a file that did not contain the password.
    console.log(`Admin created: ${adminEmail} (password written to ${credFile})`);
  }
  console.log("Seed complete");
}

// `.finally` alone swallowed the failure into an unhandled rejection: the seed
// exited with a stack trace and, depending on the Node version, a zero status —
// so a failed seed inside deploy-staging.sh's `|| true` looked like a clean run.
main()
  .then(() => db.$disconnect())
  .catch(async (e) => {
    console.error("Seed FAILED:", e);
    await db.$disconnect().catch(() => {});
    process.exit(1);
  });

/**
 * Seed sensible per-game pricing tiers (GamePlan rows).
 *
 * For each tier we pick:
 *   - basePlanId   = the smallest active VPS Plan whose ramMB >= the tier's ramMB
 *                    (falls back to the largest plan if none is big enough).
 *   - osTemplateId = that game's OsTemplate (family=<game>, category=APPLICATION),
 *                    if one exists; otherwise null (deploy resolves it at runtime).
 *
 * Idempotent: dedupes by (gameFamily, name) and upserts.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-gameplans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type TierSpec = {
  gameFamily: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number;
  priceCents: number;
  featured?: boolean;
};

// Retail prices in cents, monthly term. RAM/slots/price differ per game.
const TIERS: TierSpec[] = [
  // Minecraft — light, scales by player count.
  { gameFamily: "minecraft", name: "Minecraft — 2 GB / 10 slots", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 10, priceCents: 499 },
  { gameFamily: "minecraft", name: "Minecraft — 4 GB / 20 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 899, featured: true },
  { gameFamily: "minecraft", name: "Minecraft — 8 GB / 50 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 50, priceCents: 1599 },

  // Valheim — RAM-hungry world simulation.
  { gameFamily: "valheim", name: "Valheim — 4 GB / 10 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 10, priceCents: 999 },
  { gameFamily: "valheim", name: "Valheim — 8 GB / 20 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 20, priceCents: 1699, featured: true },

  // Rust — needs the most RAM & CPU, big populations.
  { gameFamily: "rust", name: "Rust — 4 GB / 40 slots", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 40, priceCents: 1299 },
  { gameFamily: "rust", name: "Rust — 6 GB / 60 slots", ramMB: 6144, cpuCores: 3, diskGB: 60, slots: 60, priceCents: 1799, featured: true },
  { gameFamily: "rust", name: "Rust — 10 GB / 150 slots", ramMB: 10240, cpuCores: 4, diskGB: 80, slots: 150, priceCents: 2999 },

  // Palworld — heavy, small-ish parties.
  { gameFamily: "palworld", name: "Palworld — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 8, priceCents: 1499 },
  { gameFamily: "palworld", name: "Palworld — 16 GB / 32 players", ramMB: 16384, cpuCores: 4, diskGB: 80, slots: 32, priceCents: 2799, featured: true },

  // CS2 — competitive FPS, modest RAM.
  { gameFamily: "cs2", name: "CS2 — 2 GB / 12 slots", ramMB: 2048, cpuCores: 2, diskGB: 40, slots: 12, priceCents: 699 },
  { gameFamily: "cs2", name: "CS2 — 4 GB / 24 slots", ramMB: 4096, cpuCores: 3, diskGB: 50, slots: 24, priceCents: 1199, featured: true },

  // Terraria — lightweight sandbox.
  { gameFamily: "terraria", name: "Terraria — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 20, slots: 8, priceCents: 449 },
  { gameFamily: "terraria", name: "Terraria — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 16, priceCents: 799, featured: true },
];

async function main() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) {
    throw new Error("No active VPS plans found — run the main seed first (npx prisma db seed).");
  }
  const largest = plans[plans.length - 1];

  // Cache the first game image per family.
  const imageByFamily = new Map<string, string>();
  for (const spec of TIERS) {
    if (imageByFamily.has(spec.gameFamily)) continue;
    const os = await db.osTemplate.findFirst({
      where: { family: spec.gameFamily, category: "APPLICATION" },
      orderBy: { sortOrder: "asc" },
    });
    imageByFamily.set(spec.gameFamily, os?.id ?? "");
  }

  let created = 0;
  let updated = 0;
  let sortByGame = new Map<string, number>();

  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = imageByFamily.get(spec.gameFamily) || null;
    const sortOrder = (sortByGame.get(spec.gameFamily) ?? 0);
    sortByGame.set(spec.gameFamily, sortOrder + 1);

    const data = {
      gameFamily: spec.gameFamily,
      name: spec.name,
      ramMB: spec.ramMB,
      cpuCores: spec.cpuCores,
      diskGB: spec.diskGB,
      slots: spec.slots,
      priceCents: spec.priceCents,
      termMonths: 1,
      basePlanId: basePlan.id,
      osTemplateId: osId,
      featured: spec.featured ?? false,
      active: true,
      sortOrder,
    };

    // Dedupe by (gameFamily, name) — no DB unique constraint exists on the pair.
    const existing = await db.gamePlan.findFirst({
      where: { gameFamily: spec.gameFamily, name: spec.name },
    });
    if (existing) {
      await db.gamePlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.gamePlan.create({ data });
      created++;
    }
    console.log(
      `  ${spec.gameFamily.padEnd(10)} ${spec.name.padEnd(32)} → base=${basePlan.name} img=${osId ? "yes" : "auto"}`,
    );
  }

  const total = await db.gamePlan.count();
  console.log(`\nGamePlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

/**
 * Seed the Business Email mailbox-hosting tiers (EmailPlan rows).
 *
 * Three sensible tiers priced per month:
 *   - Starter  : 1 mailbox  / 10 GB each
 *   - Business : 5 mailboxes / 25 GB each
 *   - Pro      : 25 mailboxes / 50 GB each
 *
 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-email-plans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type TierSpec = {
  name: string;
  mailboxes: number;
  storageGB: number;
  priceCents: number;
  termMonths: number;
  sortOrder: number;
};

const TIERS: TierSpec[] = [
  { name: "Starter", mailboxes: 1, storageGB: 10, priceCents: 199, termMonths: 1, sortOrder: 0 },
  { name: "Business", mailboxes: 5, storageGB: 25, priceCents: 799, termMonths: 1, sortOrder: 1 },
  { name: "Pro", mailboxes: 25, storageGB: 50, priceCents: 2499, termMonths: 1, sortOrder: 2 },
];

async function main() {
  let created = 0;
  let updated = 0;

  for (const spec of TIERS) {
    const data = {
      name: spec.name,
      mailboxes: spec.mailboxes,
      storageGB: spec.storageGB,
      priceCents: spec.priceCents,
      termMonths: spec.termMonths,
      active: true,
      sortOrder: spec.sortOrder,
    };

    // No DB unique constraint on name — dedupe manually.
    const existing = await db.emailPlan.findFirst({ where: { name: spec.name } });
    if (existing) {
      await db.emailPlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.emailPlan.create({ data });
      created++;
    }
    console.log(
      `  ${spec.name.padEnd(10)} ${spec.mailboxes} mailbox(es) · ${spec.storageGB} GB each · ${(spec.priceCents / 100).toFixed(2)}/${spec.termMonths}mo`,
    );
  }

  const total = await db.emailPlan.count();
  console.log(`\nEmailPlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
